using System;
using System.Collections.Generic;
using System.Reflection;
using System.Text;
using UnityEngine;
using UnityEngine.UI;
using Kamilunavo.RisingSteps.Core;
using Kamilunavo.RisingSteps.Gameplay;
using Kamilunavo.RisingSteps.UI;
public static class RisingRealmCollectionValidation
{
 static int checks;static readonly BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;static List<string> failures;
 static void Check(bool value,string message){checks++;if(!value)failures.Add(message);}
 public static void Validate(){checks=0;failures=new List<string>();foreach(var pane in new[]{new Vector2(375,627),new Vector2(734,343),new Vector2(190,627)})foreach(var lang in new[]{"de","en"})try{Fixture(pane,lang);}catch(Exception e){failures.Add(pane+lang+": "+e.GetBaseException().Message);}if(failures.Count>0)throw new Exception("RISING_REALM_COLLECTION: "+string.Join("; ",failures));Debug.Log("RISING_REALM_COLLECTION_PASS checks="+checks);}
 static void Fixture(Vector2 pane,string language){var root=new GameObject("RealmCollectionFixture");Canvas canvas=null;try{var course=root.AddComponent<RisingCourse>();var profile=new RisingProfile{TutorialDone=true,Language=language,UnlockedRealm=9,LevelStars=new int[100],Stars=new int[10],Crystals=428};for(int i=0;i<100;i++)profile.LevelStars[i]=1;typeof(RisingCourse).GetField("<Profile>k__BackingField",Private).SetValue(course,profile);course.Player=new GameObject("Player").transform;course.Player.SetParent(root.transform);var hud=root.AddComponent<RisingHud>();hud.Initialize(course);var safe=(RectTransform)typeof(RisingHud).GetField("_safe",Private).GetValue(hud);canvas=safe.GetComponentInParent<Canvas>();canvas.GetComponent<CanvasScaler>().enabled=false;canvas.scaleFactor=3;UiMetrics.QaPointScale=3;safe.GetComponent<SafeAreaFitter>().enabled=false;safe.anchorMin=safe.anchorMax=Vector2.one*.5f;safe.sizeDelta=pane;typeof(RisingHud).GetMethod("Layout",Private).Invoke(hud,null);Remove(hud);hud.ShowHome();Canvas.ForceUpdateCanvases();var content=safe.Find("ModalBackdrop/ModalCard/Viewport/Content");int realms=0;foreach(Transform child in content)if(child.name.StartsWith("Realm")&&int.TryParse(child.name.Substring(5),out _))realms++;Check(realms==10,pane+language+" gallery exposes ten realm cards instead of three");var catalog=typeof(RisingProfile).Assembly.GetType("Kamilunavo.RisingSteps.Core.RisingRealmCatalog");Check(catalog!=null&&Convert.ToInt32(catalog.GetField("Count").GetValue(null))==10,"shared realm catalog carries ten named identities");Remove(hud);hud.ShowSettings();Check(safe.Find("ModalBackdrop/ModalCard/Viewport/Content/Music")!=null,"settings expose separate Music action alongside Sound");Remove(hud);hud.ShowHome();Canvas.ForceUpdateCanvases();content=safe.Find("ModalBackdrop/ModalCard/Viewport/Content");if(realms!=10)return;
  var chapters=new[]{Resources.Load<Texture2D>("Art/MeadowChapter-v2"),Resources.Load<Texture2D>("Art/CascadeChapter-v2"),Resources.Load<Texture2D>("Art/RisingStepsIcon")};for(int i=0;i<3;i++)Check(chapters[i]!=null&&content.Find("Realm"+i+"/RealmArt")?.GetComponent<RawImage>()?.texture==chapters[i],"three distinct authored chapter subjects load correctly "+i);
  var identities=new HashSet<string>();var silhouettes=new HashSet<string>();
  for(int realm=0;realm<10;realm++){Check(identities.Add(RisingRealmCatalog.Name(realm,language!="en")),"ten realm names are distinct "+realm);var card=content.Find("Realm"+realm);Check(card!=null&&card.GetComponent<Button>().interactable,"unlocked realm remains selectable "+realm);var bounds=UiMetrics.ScreenRect((RectTransform)card);Check(bounds.width/3>=48&&bounds.height/3>=48,"realm touch target >=48 "+realm);if(realm<3)continue;var art=card.Find("RealmArt").GetComponent<RealmScenePreview>();Check(art!=null&&art.Realm==realm&&!art.raycastTarget&&art.texture is RenderTexture,"new realm owns actual 3D scenic preview "+realm);if(art==null)continue;var signature=new StringBuilder();foreach(var filter in art.SceneRoot.GetComponentsInChildren<MeshFilter>())signature.Append(filter.name).Append(':').Append(filter.sharedMesh.vertexCount).Append(';');Check(silhouettes.Add(signature.ToString()),"shipping scene geometry differs independently of palette "+realm);}
  Check(silhouettes.Count==7,"seven new realm thumbnails have seven different shipping scene topologies");
  var meadow=content.Find("Realm0/RealmArt").GetComponent<RawImage>();var waterfall=content.Find("Realm1/RealmArt").GetComponent<RawImage>();Check(meadow.uvRect!=waterfall.uvRect,"legacy meadow and waterfall keep separate authored crop subjects");
  var viewport=content.GetComponentInParent<ScrollRect>();viewport.verticalNormalizedPosition=0;Canvas.ForceUpdateCanvases();var last=UiMetrics.ScreenRect((RectTransform)content.Find("Tutorial"));var window=UiMetrics.ScreenRect(viewport.viewport);Check(last.yMin>=window.yMin-.5f&&last.yMax<=window.yMax+.5f,"collection scroll reaches the last utility action");
  var tags=new HashSet<int>();for(int realm=0;realm<10;realm++){Remove(hud);hud.ShowLevels(realm);Canvas.ForceUpdateCanvases();content=safe.Find("ModalBackdrop/ModalCard/Viewport/Content");int levels=0;foreach(Transform child in content)if(child.name.StartsWith("Level")&&int.TryParse(child.name.Substring(5),out int level)){levels++;var tag=child.GetComponent("RealmRouteTag");Check(tag!=null,"route card has explicit realm/level tag "+realm+"/"+level);if(tag!=null){var type=tag.GetType();int id=(int)type.GetProperty("Id").GetValue(tag);Check((int)type.GetField("Realm").GetValue(tag)==realm&&(int)type.GetField("Level").GetValue(tag)==level,"route card preserves exact realm/local-level "+realm+"/"+level);tags.Add(id);}var rect=UiMetrics.ScreenRect((RectTransform)child);Check(rect.width/3>=48&&rect.height/3>=48,"route target >=48 "+realm+"/"+level);}Check(levels==10,"realm keeps ten-route picker "+realm);}
  Check(tags.Count==100,"one hundred route IDs stay distinct without reordering original thirty");Check(profile.Crystals==428&&course.Paused,"gallery preserves wallet and gameplay pause");
 }finally{UiMetrics.QaPointScale=null;if(canvas!=null)UnityEngine.Object.DestroyImmediate(canvas.gameObject);UnityEngine.Object.DestroyImmediate(root);}}
 public static void ValidateScenePreviews()
 {
  checks=0;failures=new List<string>();var previewType=typeof(RisingHud).Assembly.GetType("Kamilunavo.RisingSteps.UI.RealmScenePreview");Check(previewType!=null,"seven new realm cards use actual 3D scene previews");
  var skybox=RenderSettings.skybox;var ambient=RenderSettings.ambientLight;bool fog=RenderSettings.fog;var roots=new List<GameObject>();var scenes=new List<GameObject>();var targets=new List<RenderTexture>();var topology=new HashSet<string>();
  string[] landmarks={"JungleCanopy","CrystalGeode","FrostFir","DesertWindArch","VolcanoLavaChannel","CloudCoastSeaArch","StarlitCrescent"};string[] horizons={"JungleHorizon","CrystalHorizon","FrostHorizon","DesertHorizon","VolcanoHorizon","CloudCoastHorizon","StarlitHorizon"};
  try{
   for(int realm=3;realm<10;realm++){
    var host=new GameObject("PreviewFixture"+realm,typeof(RectTransform));roots.Add(host);((RectTransform)host.transform).sizeDelta=new Vector2(120,100);
    var graphic=RealmIllustration.Add(host.transform,realm,Vector2.zero,Vector2.one);var raw=graphic as RawImage;Check(raw!=null&&raw.texture is RenderTexture,"realm "+realm+" owns a real RawImage render target");var scene=graphic.GetType().GetProperty("SceneRoot")?.GetValue(graphic) as GameObject;Check(scene!=null,"realm "+realm+" exposes actual scene provenance");if(scene==null)continue;scenes.Add(scene);targets.Add(raw?.texture as RenderTexture);
    Check(scene.transform.Find("ActualIsland")!=null,"shipping IslandArt forms the foreground "+realm);var landmark=false;var horizon=false;var signature=new StringBuilder();foreach(var child in scene.GetComponentsInChildren<Transform>()){landmark|=child.name==landmarks[realm-3];horizon|=child.name==horizons[realm-3];if(child.TryGetComponent<MeshFilter>(out var filter)&&filter.sharedMesh!=null){signature.Append(child.name).Append(':').Append(filter.sharedMesh.vertexCount).Append(';');}Check(child.gameObject.layer==31,"preview scene stays on isolated layer31 "+realm);}
    Check(landmark&&horizon,"realm has recognizable shipping landmark and actual backdrop "+realm);Check(topology.Add(signature.ToString()),"seven actual scene topologies differ "+realm);Check(scene.GetComponentsInChildren<Collider>().Length==0&&scene.GetComponentsInChildren<StepMarker>().Length==0,"scenic thumbnails own no gameplay colliders or route markers "+realm);
    var cameras=scene.GetComponentsInChildren<Camera>();Check(cameras.Length==1&&!cameras[0].enabled&&cameras[0].cullingMask==(1<<31)&&cameras[0].targetTexture==raw.texture,"one isolated manual camera owns its target "+realm);Check(scene.GetComponentsInChildren<AudioListener>().Length==0,"preview never adds an audio listener "+realm);foreach(var lamp in scene.GetComponentsInChildren<Light>())Check(lamp.cullingMask==(1<<31)&&lamp.type!=LightType.Directional,"studio lighting remains local "+realm);
   }
   if(previewType!=null){var leases=previewType.GetProperty("ActiveLeaseCount");Check(leases!=null&&(int)leases.GetValue(null)==7,"seven thumbnails occupy seven finite scene leases");}
   Check(RenderSettings.skybox==skybox&&RenderSettings.ambientLight==ambient&&RenderSettings.fog==fog,"previews never mutate global sky, ambient light or fog");
  }finally{foreach(var host in roots)UnityEngine.Object.DestroyImmediate(host);}
  foreach(var scene in scenes)Check(scene==null,"preview scene is destroyed with its image");foreach(var target in targets)Check(target==null,"owned render target is destroyed with its image");if(previewType!=null)Check((int)previewType.GetProperty("ActiveLeaseCount").GetValue(null)==0,"all finite scene leases return after teardown");
  if(failures.Count>0)throw new Exception("RISING_REALM_SCENE_PREVIEW: "+string.Join("; ",failures));Debug.Log("RISING_REALM_SCENE_PREVIEW_PASS checks="+checks);
 }
 static void Remove(RisingHud hud){var field=typeof(RisingHud).GetField("_modal",Private);var modal=(RectTransform)field.GetValue(hud);if(modal!=null)UnityEngine.Object.DestroyImmediate(modal.gameObject);field.SetValue(hud,null);}
}
#endif
